(2650, 'theme_boost_union', 'enableaccessibilitydeclaration', 'no'),
(2651, 'theme_boost_union', 'accessibilitydeclarationcontent', ''),
(2652, 'theme_boost_union', 'accessibilitydeclarationpagetitle', 'Declaration of accessibility'),
(2653, 'theme_boost_union', 'accessibilitydeclarationlinkposition', 'none'),
(2654, 'theme_boost_union', 'enableaccessibilitysupport', 'no'),
(2655, 'theme_boost_union', 'accessibilitysupportcontent', '<p>If you have any accessibility feedback or want to report a barrier, please use the form below.</p>\r\n<p>Do you work with assistive technology such as screen readers, magnifiers, voice control or speech recognition software? If yes, please specify which ones. To help us to process your request, you can allow the form to automatically send the following information along with your message: The URL on which you were when you opened this support form (this is called \'referrer\') and some information about your browser.</p>'),
(2656, 'theme_boost_union', 'accessibilitysupportpagetitle', 'Accessibility support'),
(2657, 'theme_boost_union', 'accessibilitysupportlinkposition', 'none'),
(2658, 'theme_boost_union', 'allowaccessibilitysupportwithoutlogin', 'no'),
(2659, 'theme_boost_union', 'enableaccessibilitysupportfooterbutton', 'no'),
(2660, 'theme_boost_union', 'allowanonymoussubmits', 'no'),
(2661, 'theme_boost_union', 'allowsendtechinfoalong', 'yes'),
(2662, 'theme_boost_union', 'accessibilitysupportusermail', ''),
(2663, 'theme_boost_union', 'accessibilitysupportpagesrlinktitle', 'Get accessibility support'),
