(2667, 'theme_boost_union', 'uploadedsnippets', ''),
(2668, 'theme_moove', 'sliderimage1', '/gt4t_hero.png'),
(2669, 'theme_moove', 'slidertitle1', 'GreenTech4Transformation (GT4T)'),
(2670, 'theme_moove', 'slidercontent1', 'A project funded by the EIT Higher Education Initiative and coordinated by Satakunta University of Applied Sciences (SAMK, Finland).'),
(2671, 'theme_moove', 'sliderbutton1', 'Get Started'),
(2672, 'theme_moove', 'sliderurl1', '/login/index.php'),
(2673, 'theme_moove', 'marketingicon1', '1'),
(2674, 'theme_moove', 'marketingicon2', '1'),
(2675, 'theme_moove', 'marketingicon3', '1'),
(2676, 'theme_moove', 'marketingicon4', '1'),
(2677, 'theme_moove', 'marketingheading1', 'Circular Economy'),
(2678, 'theme_moove', 'marketingcontent1', 'Learn how to design out waste, keep products and materials in use, and regenerate natural systems through circular business models.'),
(2679, 'theme_moove', 'marketingheading2', 'Digital Transformation'),
(2680, 'theme_moove', 'marketingcontent2', 'Explore how digital technologies drive organisational change, create new value and enable smarter, more connected societies.'),
(2681, 'theme_moove', 'marketingheading3', 'Energy Transition'),
(2682, 'theme_moove', 'marketingcontent3', 'Understand the global shift from fossil fuels to renewable energy sources and discover the policies, technologies and skills needed for a net-zero world.'),
(2683, 'theme_moove', 'marketingheading4', 'Venture Science Center');
INSERT INTO `mdl_config_plugins` (`id`, `plugin`, `name`, `value`) VALUES
(2684, 'theme_moove', 'marketingcontent4', 'Bridge the gap between academic research and real-world impact by turning scientific breakthroughs into sustainable ventures and societal solutions.'),
(2685, 'theme_moove', 'numberscustomtitle', 'GT4T in Numbers'),
(2686, 'theme_moove', 'numberscustomdesc', 'A growing community of learners, educators and partners united by a shared commitment to green and digital transformation.'),
(2687, 'theme_moove', 'faqquestion1', 'What is GT4T?'),
(2688, 'theme_moove', 'faqanswer1', '<p>GreenTech4Transformation (GT4T) is a project funded by the EIT Higher Education Initiative and coordinated by Satakunta University of Applied Sciences (SAMK, Finland). It strengthens universities\' role in the green and digital transition by connecting higher education with industry and innovation ecosystems.</p>'),
(2689, 'theme_moove', 'faqquestion2', 'Who can participate in GT4T programmes?'),
(2690, 'theme_moove', 'faqanswer2', '<p>GT4T programmes are open to students, staff, and partners from DIVERSE alliance universities. Mixed, cross-border teams work on real challenges from companies and regional ecosystems.</p>'),
(2691, 'theme_moove', 'faqquestion3', 'How does GT4T collaborate with industry?'),
(2692, 'theme_moove', 'faqanswer3', '<p>Partner universities deliver joint training and hands-on innovation projects. Teams apply innovation methodologies, idea validation, value proposition development, pitching preparation, and early-stage commercialisation awareness to real industry challenges.</p>'),
(2693, 'theme_moove', 'faqquestion4', 'What is the Venture Science Center?'),
(2694, 'theme_moove', 'faqanswer4', '<p>Venture Science Center–type hubs provide a permanent home for training, prototyping, and ecosystem engagement. They support pilots, proof-of-concepts, cross-border research-to-business connections, and systematic entrepreneurship education.</p>'),
(2695, 'theme_moove', 'customscss', '/* GT4T brand overrides */\n:root {\n    --bs-primary: #1DC71D;\n    --bs-link-color: #1DC71D;\n}'),
(2696, 'auth_gt4t_validator', 'version', '2024010101'),
(2697, 'auth_gt4t_validator', 'apiurl', 'https://example.com/api/validate-student'),
(2698, 'auth_gt4t_validator', 'apikey', ''),
(2699, 'cachestore_redis', 'test_serializer', '1'),
(2700, 'theme_moove', 'themerev', '1779897414'),
(2701, 'theme_boost_union', 'themerev', '1779829659');
