INSERT INTO `mdl_notifications` (`id`, `useridfrom`, `useridto`, `subject`, `fullmessage`, `fullmessageformat`, `fullmessagehtml`, `smallmessage`, `component`, `eventtype`, `contexturl`, `contexturlname`, `timeread`, `timecreated`, `customdata`) VALUES
(2, 2, 2, 'Moodle updates are available (https://thinkhub.club)', 'Update notifications\n\nThere is a newer Moodle version available!\nMoodle 5.2+ (Build: 20260519) Version 2026042000.04 (Stable version)\nMoodle 5.1.4+ (Build: 20260519) Version 2025100604.04 (Stable version)\n\nSee https://thinkhub.club/admin/index.php for more details\n\nIt is strongly recommended that you update your site to the latest version to obtain all recent security and bug fixes.\n\nYour Moodle site https://thinkhub.club is configured to automatically check for available updates. You are receiving this message as the administrator of the site. You can disable automatic checks for available updates in Site administration / Server / Update notifications or customise the delivery of this message via your preferences page.\n', 2, '<h1>Update notifications</h1>\n<h2>There is a newer Moodle version available!</h2>\n<ul>\n<li><strong>Moodle 5.2+ (Build: 20260519)</strong> Version 2026042000.04 (Stable version)</li>\n<li><strong>Moodle 5.1.4+ (Build: 20260519)</strong> Version 2025100604.04 (Stable version)</li>\n</ul>\n<p>See <a href=\"https://thinkhub.club/admin/index.php\">https://thinkhub.club/admin/index.php</a> for more details</p>\n<p>It is strongly recommended that you update your site to the latest version to obtain all recent security and bug fixes.</p>\n<footer><p style=\"font-size:smaller; color:#333;\">Your Moodle site <a href=\"https://thinkhub.club\">https://thinkhub.club</a> is configured to automatically check for available updates. You are receiving this message as the administrator of the site. You can disable automatic checks for available updates in Site administration / Server / Update notifications or customise the delivery of this message via your preferences page.</p></footer>', 'Update notifications', 'moodle', 'availableupdate', NULL, NULL, NULL, 1779460654, NULL),
(3, 2, 7, 'Welcome to Introduction to Programming', 'Hi Student, you are enrolled in the course Introduction to Programming.', 4, 'Hi Student, you are enrolled in the course Introduction to Programming.', NULL, 'moodle', 'enrolcoursewelcomemessage', 'https://thinkhub.club/user/view.php?id=7&amp;course=4', 'Introduction to Programming', NULL, 1779487649, NULL),
